#include <stdio.h>

int main(void) {
    int n, t;
    if (scanf("%d %d", &n, &t) != 2) return 0;

    long long answer;

    if (t == 0) {
        answer = n;
    } else if (t == 1) {
        answer = (long long)n * (n - 1);
    } else {
        answer = n >= 3 ? (long long)n * (n - 1) * (n - 2) / 6 : 0;
    }

    printf("%lld\n", answer);
    return 0;
}
```

